mapper.select:
SELECT primary_key, source, contract_name, contract_number,contract_type,
buyer,seller, vender_code,vender_contact, enterprise_code,
user_code, language, payment_strategy, column_titles,
amount_title, product_detail,
state,contract_time, data_version,
sign_areas,purchase_contract,sell_quotation,buyer_quotation,cancel_reason,
delete_flag,business_belong
FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND user_code = #{userCode}
AND delete_flag= 'f'

    AND contract_number LIKE '%'|| #{contractNumber} ||'%'


    AND contract_time >= #{contractTimePreDate}


    AND contract_time <= #{contractTimePostDate}


    AND business_belong = #{businessBelong}

ORDER BY create_time DESC

SELECT primary_key, source, contract_name, contract_number, contract_type,
buyer, seller, vender_code,vender_contact, enterprise_code,
user_code,  language, payment_strategy, column_titles,
amount_title, state, clauses_chs, clauses_en, product_detail,
contract_time, data_version,
sign_areas, purchase_contract, sell_quotation, buyer_quotation, temp_data,
attachments,business_belong,qrcode_generated_flag
FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND user_code= #{userCode}
AND primary_key= #{contractCode}

